mapper.select:
SELECT * , ROW_NUMBER() OVER (ORDER BY A.ref, A.ansnum desc,A.step desc) AS rownum FROM ( select A.* , FORMAT(A.wdate, 'yyyy-MM-dd') AS formatted_date , KCC_EGIS.egis.FN_MASK_NAME(writer) writer2 , (SELECT COUNT(*) FROM KCC_EGIS.egis.TBL_FREE_TAIL b WHERE b.info_num = A.num) AS tail_count , ROW_NUMBER() OVER (PARTITION BY A.num ORDER BY A.num) AS SEQ from ( select a.* from KCC_EGIS.egis.TBL_FREE a where 1=2 and a.chk_del = 'N'
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and a.subject LIKE CONCAT('%', #{searchKeyword}, '%')
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and CONTAINS(a.content, #{searchKeyword})
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and a.writer LIKE CONCAT('%', #{searchKeyword}, '%')
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and a.num in (select distinct info_num FROM KCC_EGIS.egis.TBL_FREE_TAIL where CONTAINS(content, #{searchKeyword}))
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{chk_del}
and a.num in (select distinct info_num FROM KCC_EGIS.egis.TBL_FREE_TAIL where writer LIKE CONCAT('%', #{searchKeyword}, '%'))
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
) A ) A WHERE A.SEQ = 1 ORDER BY ref desc, ansnum,step

select count(*) from ( SELECT * FROM ( select A.* , FORMAT(a.wdate, 'yyyy.MM.dd') AS reg_date , KCC_EGIS.egis.FN_MASK_NAME(writer) writer2 , ROW_NUMBER() OVER (ORDER BY a.num) AS rownum , (SELECT COUNT(*) FROM KCC_EGIS.egis.TBL_FREE_TAIL b WHERE b.info_num = a.num) AS tail_count , ROW_NUMBER() OVER (PARTITION BY A.num ORDER BY A.num) AS SEQ from ( select a.* from KCC_EGIS.egis.TBL_FREE a where 1=2 and a.chk_del = 'N'
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and a.subject LIKE CONCAT('%', #{searchKeyword}, '%')
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{chk_del}
and CONTAINS(a.content, #{searchKeyword})
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and a.writer LIKE CONCAT('%', #{searchKeyword}, '%')
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and a.num in (select distinct info_num FROM KCC_EGIS.egis.TBL_FREE_TAIL where CONTAINS(content, #{searchKeyword}))
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
and a.num in (select distinct info_num FROM KCC_EGIS.egis.TBL_FREE_TAIL where writer LIKE CONCAT('%', #{searchKeyword}, '%'))
union all select a.* from KCC_EGIS.egis.TBL_FREE a where 1=1
and a.chk_del = #{searchChk_del}
) A ) A WHERE A.SEQ = 1 ) A

select count(*) from (
	select *,FORMAT(wdate , 'yyyy.MM.dd') AS formatted_date,
    FORMAT(wdate, 'HH:mm:ss') AS formatted_time
    from KCC_EGIS.egis.TBL_FREE_TAIL
	where info_num = #{info_num}
) A

mapper.insert:
insert into KCC_EGIS.egis.TBL_FREE_TAIL (
	 info_num, id, writer, content, ip, wdate  
)values(
	 #{info_num}, #{id}, #{writer}, #{content}, #{ip}, getdate()
)
